SZGame2D.onStart(function __szProjectRun() {
  const __szProjectRunContext = window.__SZProjectLifecycle.begin(() => SZGame2D.restart());
  // Ao iniciar
  SZGame2D.setupStage(800, 480, "#07162e");
  const nave = SZGame2D.createShip({ x: 400, y: 410, w: 54, h: 62, body: "#35e8ff", wings: "#2568ff" });
  const tiros = SZGame2D.createGroup();
  const asteroides = SZGame2D.createGroup();
  let pontos = 0;
  SZGame2D.setHealth(nave, 3);
  const alvo = 26;
  SZGame2D.setScene("inicio");
  // Quando acontecer
  SZGame2D.onKey("Space", () => {
    if (SZGame2D.sceneIs("jogando")) {
      SZGame2D.spawnBullet(tiros, { x: SZGame2D.centerX(nave), y: SZGame2D.spriteY(nave), radius: 5, color: "#9cff57", vx: 0, vy: -9 });
      SZGame2D.playFx("shoot");
    }
  }, "nave-ref-92");
  SZGame2D.onKey("Enter", () => {
    if (SZGame2D.sceneIs("inicio")) {
      SZGame2D.setScene("jogando");
    } else if (SZGame2D.sceneIs("fim")) {
      SZGame2D.restart();
    } else if (SZGame2D.sceneIs("vitoria")) {
      SZGame2D.restart();
    }
  }, "nave-ref-102");
  // Enquanto estiver rodando
  // O jogo roda 60 passos por segundo: cada volta desenha um "quadro" do filme.
  SZGame2D.gameLoop(function update() {
    if (SZGame2D.sceneIs("jogando")) {
      SZGame2D.clear();
      SZGame2D.drawStarfield(ctx, 1);
      SZGame2D.arrowsX(nave, 7);
      SZGame2D.clampToScreen(nave, ctx);
      SZGame2D.drawSprite(ctx, nave);
      SZGame2D.updateGroup(tiros);
      SZGame2D.pruneOffscreen(ctx, tiros, 40, (sprite) => {

      });
      SZGame2D.drawGroup(ctx, tiros);
      SZGame2D.updateGroup(asteroides);
      SZGame2D.pruneOffscreen(ctx, asteroides, 40, (sprite) => {

      });
      SZGame2D.drawGroup(ctx, asteroides);
      SZGame2D.overlapGroups(tiros, asteroides, (tiro, asteroide) => {
        SZGame2D.removeFromGroup(tiros, tiro);
        SZGame2D.removeFromGroup(asteroides, asteroide);
        SZGame2D.explodeSprite(asteroide, "#ffb13b");
        SZGame2D.playFx("explosion");
        pontos = pontos + 1;
      });
      SZGame2D.drawScore(ctx, "Pontos:", pontos, 12, 30, "#ffffff", 24);
      SZGame2D.overlapSpriteGroup(() => nave, asteroides, (inimigo) => {
        SZGame2D.removeFromGroup(asteroides, inimigo);
        SZGame2D.explodeSprite(inimigo, "#ffb13b");
        SZGame2D.damageSprite(nave, 1, 45);
        SZGame2D.shake(ctx, 8);
      });
      SZGame2D.drawSpriteHealth(ctx, nave, "hearts", 12, 48, 22, "#ff5d5d");
      if (pontos >= alvo) {
        SZGame2D.setScene("vitoria");
      }
      if (SZGame2D.healthDepleted(nave)) {
        SZGame2D.setScene("fim");
      }
    } else if (SZGame2D.sceneIs("inicio")) {
      SZGame2D.showScreen(ctx, "Nave contra Asteroides", "Destrua os asteroides", "Aperte Enter para começar", "#112b46");
    } else if (SZGame2D.sceneIs("vitoria")) {
      SZGame2D.showScreen(ctx, "Você ganhou!", "", "Aperte Enter para voltar ao início", "#112b46");
    } else if (SZGame2D.sceneIs("fim")) {
      SZGame2D.showScreen(ctx, "Você perdeu", "", "Aperte Enter para voltar ao início", "#112b46");
    }
  }, "nave-ref-19");
  SZGame2D.gameLoop(function __szPeriodicLoop() {
    if (SZGame2D.everyFrames("cada", 40)) {
      if (SZGame2D.sceneIs("jogando")) {
        SZGame2D.spawnAsteroid(asteroides, { x: SZGame2D.randomX(), y: -30, size: 40, color: "#8d8f9b", vx: 0, vy: 3 });
      }
    }
  });
}, "__sz-project");
